content:
@import url("../../styles.css");

.skip-link {
  position: absolute;
  left: 16px;
  top: -48px;
  z-index: 100;
  padding: 10px 14px;
  border-radius: 999px;
  background: #0f6abf;
  color: #fff;
  text-decoration: none;
  font-weight: 700;
  box-shadow: 0 12px 28px rgba(15, 106, 191, 0.25);
  transition: top 140ms ease;
}

.skip-link:focus {
  top: 14px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
